<script setup>import{Head,Link,useForm}from'@inertiajs/vue3';import AppLayout from'../../../Layouts/AppLayout.vue';import PageBanner from'../../../Components/PageBanner.vue';import Pagination from'../../../Components/Pagination.vue';defineOptions({layout:AppLayout});defineProps({reconciliations:Object,vendors:Array,can_generate:Boolean});const form=useForm({vendor_id:'',period_start:'',period_end:''});</script>
<template><Head title="BA Rekonsiliasi"/><div class="units-page"><PageBanner title="BA Rekonsiliasi" description="Rekonsiliasi bulanan saldo consignment antara Warehouse dan Vendor." icon="checkCircle"/><section v-if="can_generate" class="surface-card form-stack"><h2>Buat BA baru</h2><div class="form-grid"><select v-model="form.vendor_id" class="form-input"><option value="">Pilih vendor</option><option v-for="vendor in vendors" :key="vendor.id" :value="vendor.id">{{vendor.vendor_code}} · {{vendor.vendor_name}}</option></select><input v-model="form.period_start" type="date" class="form-input"/><input v-model="form.period_end" type="date" class="form-input"/><button class="button button--primary" :disabled="form.processing" @click="form.post('/monitoring/reconciliations')">Buat BA</button></div></section><section class="surface-card"><div class="table-scroll"><table class="data-table"><thead><tr><th>Nomor BA</th><th>Vendor</th><th>Periode</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="row in reconciliations.data" :key="row.id"><td>{{row.ba_number}}</td><td>{{row.vendor?.vendor_name}}</td><td>{{row.period_start}} – {{row.period_end}}</td><td>{{row.status}}</td><td><Link :href="`/monitoring/reconciliations/${row.id}`" class="text-button">Detail</Link></td></tr></tbody></table></div><p v-if="!reconciliations.data.length" class="page-note">Belum ada BA Rekonsiliasi.</p><Pagination :paginator="reconciliations" noun="BA"/></section></div></template>
